import React, { useState, useRef } from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  LayoutAnimation,
  UIManager,
  Platform,
  StyleSheet,
  FlatList,
} from 'react-native';
import CustomMenu from '../components/CustomMenu';
import * as Config from '../helpers/Config';
import * as Icons from '../helpers/Icons';
import { heightToDp, widthToDp } from '../helpers/Responsive';

if (Platform.OS === 'android') {
  if (UIManager.setLayoutAnimationEnabledExperimental) {
    UIManager.setLayoutAnimationEnabledExperimental(true);
  }
}

const Accordion = ({ data }) => {
  const [expandedIndex, setExpandedIndex] = useState(-1);

  const toggleAccordion = index => {
    LayoutAnimation.configureNext(LayoutAnimation.Presets.easeInEaseOut);
    setExpandedIndex(index === expandedIndex ? -1 : index);
  };
  const renderChildItem = ({ item }, index) => {
    return (
      expandedIndex === index && (
        <View style={styles.content}>
          <CustomMenu
            tintColor2={Config.Colors.textColor.textColor_1}
            item={item}
            onPress={() => console.log('first')}
            bottomImg={Icons.arrow_right}
            bottomImgBGColor={Config.Colors.defaultColor}
            titleColor={Config.Colors.textColor.textColor_1}
            style={{
              box: {
                borderRadius: 10,
                borderBlockColor: Config.Colors.borderColor,
                borderBottomWidth: 0.6,
                backgroundColor: '#000',
              },
            }}
          />
        </View>
      )
    );
  };
  const renderItem = ({ item, index }) => {
    return (
      <View key={index} style={styles.item}>
        <CustomMenu
          tintColor2={Config.Colors.black}
          item={item}
          onPress={() => toggleAccordion(index)}
          bottomImg={
            expandedIndex === index ? Icons.arrow_down : Icons.arrow_forward
          }
          style={{
            box: {
              borderRadius: expandedIndex === index ? 0 : 10,
              borderBlockColor:
                expandedIndex === index
                  ? Config.Colors.borderColor
                  : Config.Colors.defaultColor,
              borderBottomWidth: 0.6,
            },
          }}
        />
        <FlatList
          renderItem={item => renderChildItem(item, index)}
          data={item?.data}
          showsVerticalScrollIndicator={false}
          // stickyHeaderIndices={[0]}
          // stickyHeaderHiddenOnScroll={true}
        />
      </View>
    );
  };
  return (
    <View style={styles.container}>
      <FlatList
        renderItem={renderItem}
        data={data}
        showsVerticalScrollIndicator={false}
      />
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    width: '100%',
    // backgroundColor: '#fff',
    // marginBottom: 10,
    // borderWidth: 1,
    // borderColor: '#ccc',
    // borderRadius: 5,
    // overflow: 'hidden',
  },
  item: {
    margin: 10,
    backgroundColor: Config.Colors.defaultColor,
    borderRadius: 10,
  },
  header: {
    padding: 15,
  },
  headerText: {
    fontSize: 16,
    fontWeight: 'bold',
  },
  content: {
    // padding: 15,
    // borderBlockColor:Config.Colors.borderColor,
    // borderBottomWidth:.6
  },
});

export default Accordion;
